<script setup>import AppShell from'../../Layouts/AppShell.vue';import StateCard from'../../Components/StateCard.vue';import PageHeader from'../../Components/PageHeader.vue';import UiButton from'../../Components/UiButton.vue';import UiCard from'../../Components/UiCard.vue';import{Head,Link}from'@inertiajs/vue3';defineProps({events:Array})</script><template><AppShell><Head title="Events"/><div class="lp-page"><PageHeader eyebrow="Events" title="All galleries" description="Create, deliver and monitor every event from one workspace."><UiButton href="/groups/create">Create event</UiButton></PageHeader><StateCard v-if="!events.length" class="mt-8" title="Your first story starts here" message="Create an event, invite participants and begin uploading photographs."><UiButton href="/groups/create" class="mt-5">Create event</UiButton></StateCard><div v-else class="mt-8 grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><Link v-for="e in events" :key="e.id" :href="`/groups/${e.id}`" class="lp-card lp-card-hover overflow-hidden"><div class="h-40 bg-gradient-to-tr from-ink to-indigo"></div><div class="p-5"><h2 class="text-lg font-bold">{{e.name}}</h2><p class="mt-2 text-sm text-slate-600">{{e.event_type||'Event'}} · {{e.photos_count}} photographs</p></div></Link></div></div></AppShell></template>
